// Открывается кнопкой ❓ в шапке или F1 (сразу на разделе текущей вкладки).
// ═══════════════════════════════════════════════════════════
const _k = s => s.split('+').map(x => `<kbd>${x}</kbd>`).join('+');
const _openKml = () => { if (typeof kmlPanelOpen !== 'undefined' && !kmlPanelOpen && typeof toggleKmlPanel === 'function') toggleKmlPanel(); };

